INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch04$PT138-S3-Q14$batch04$, 138, 3, 14, $batch04$Paradox$batch04$, $batch04$Mayor: Our city faces a difficult environmental problem caused by the enormous amount of garbage that we must dispose of. Although new recycling projects could greatly reduce this amount, these projects would actually be counterproductive to the goal of minimizing the overall amount of environmental damage.$batch04$, $batch04$Which one of the following, if true, would most help to resolve the apparent inconsistency in the mayor’s claims about new recycling projects?$batch04$, $batch04$B$batch04$, true, $batch04$Batch 04; question text from local bank.$batch04$ FROM lr_sections s WHERE s.preptest=138 AND s.section=3 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch04$PT138-S3-Q14$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$A$batch04$, $batch04$The vehicles that pick up materials for recycling create less pollution than would be caused by incinerating those materials.$batch04$, $batch04$Opposite$batch04$, false FROM lr_questions q WHERE q.qid=$batch04$PT138-S3-Q14$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$A$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$B$batch04$, $batch04$The great costs of new recycling projects would prevent other pollution-reducing projects from being undertaken.$batch04$, $batch04$Correct$batch04$, true FROM lr_questions q WHERE q.qid=$batch04$PT138-S3-Q14$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$B$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$C$batch04$, $batch04$The mayor’s city has nearly exhausted its landfill space and therefore must incinerate much of its garbage.$batch04$, $batch04$Opposite$batch04$, false FROM lr_questions q WHERE q.qid=$batch04$PT138-S3-Q14$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$C$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$D$batch04$, $batch04$More recycling would give industries in the mayor’s city a greater incentive to use recycled materials in their manufacturing processes.$batch04$, $batch04$Opposite$batch04$, false FROM lr_questions q WHERE q.qid=$batch04$PT138-S3-Q14$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$D$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$E$batch04$, $batch04$People who recycle feel less justified in consuming more than they need than do people who do not recycle.$batch04$, $batch04$Opposite$batch04$, false FROM lr_questions q WHERE q.qid=$batch04$PT138-S3-Q14$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$E$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch04$PT138-S3-Q14$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch04$Given that$batch04$, $batch04$New recycling projects could greatly reduce the city's garbage, which is a serious environmental problem.$batch04$), (1, $batch04$How can it be that$batch04$, $batch04$The mayor says the projects would work against the goal of minimizing overall environmental damage?$batch04$), (2, $batch04$Evaluate$batch04$, $batch04$Look at the word "overall." Recycling could help with garbage and still do more harm somewhere else. A hidden cost would resolve it.$batch04$), (3, $batch04$Goal$batch04$, $batch04$Find a way recycling causes more environmental harm than it prevents.$batch04$)) v(position,label,body) WHERE q.qid=$batch04$PT138-S3-Q14$batch04$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch04$A$batch04$, $batch04$Recycling trucks polluting less than incineration makes recycling look *better*.$batch04$), ($batch04$B$batch04$, $batch04$Recycling would cost so much that the city could not afford other projects that reduce pollution. The garbage problem shrinks, but the environment loses more overall.$batch04$), ($batch04$C$batch04$, $batch04$If the city has to burn its garbage, recycling would reduce burning. That makes recycling look better.$batch04$), ($batch04$D$batch04$, $batch04$More use of recycled materials in manufacturing is another benefit of recycling.$batch04$), ($batch04$E$batch04$, $batch04$Recyclers consuming less is another benefit.$batch04$)) v(letter,body) WHERE q.qid=$batch04$PT138-S3-Q14$batch04$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
